/* the box of a passive */
.aa-tree-ptip {
  box-sizing: border-box;
  width: 300px;
  padding: 10px 12px;
  background: linear-gradient(to bottom, rgba(24, 28, 38, 0.97), rgba(10, 12, 18, 0.97));
  border: 1px solid #5a5040;
  border-radius: 3px;
  box-shadow: 0 0 0 1px #000, 0 4px 12px rgba(0, 0, 0, 0.6);
  font-size: 13px;
  line-height: 1.5;
}
.aa-tree-phead {
  display: flex;
  gap: 10px;
  align-items: center;
}
.aa-tree-picon img {
  display: block;
  width: 40px;
  height: 40px;
}
.aa-tree-pkind {
  color: #bdb6a4;
  font-size: 12px;
}
.aa-tree-pname {
  color: #fff;
  font-size: 15px;
  font-weight: bold;
}
.aa-tree-sep {
  height: 0;
  margin: 7px 0;
  border-top: 1px solid #3c3a36;
}
.aa-tree-ptext {
  color: #e8e4d8;
}
/* {{PassiveLink}}: the same box inside a line of text is made of spans (a div would end the paragraph) */
.aa-skilltip-card .aa-tree-ptip,
.aa-skilltip-card .aa-tree-ptip > span {
  display: block;
}
.aa-skilltip-card .aa-tree-ptip > .aa-tree-phead {
  display: flex;
}
.aa-skilltip-card .aa-tree-ptitle,
.aa-skilltip-card .aa-tree-ptitle > span {
  display: block;
}

/* the logo at the bottom right corner of the tree: the emblem + CLASSIC picture (File:Logo.png) with the orange "+" drawn
   in CSS, the same as the top bar. Laid over the bottom edge, so the tree does not get taller */
.aa-tree-mark {
  position: absolute;
  bottom: 29px;
  right: 22px;
  display: flex;
  align-items: flex-start;
  margin: 0;
  line-height: 0;
  opacity: 0.85;
  pointer-events: none;
}
.aa-tree-mark::after {
  content: "";
  width: 16px;
  height: 16px;
  margin: 5px 0 0 2px;
  background: #f2c88f;
  clip-path: polygon(38% 12%, 44% 4%, 56% 4%, 62% 12%, 62% 38%, 88% 38%, 96% 44%, 96% 56%, 88% 62%, 62% 62%, 62% 88%, 56% 96%, 44% 96%, 38% 88%, 38% 62%, 12% 62%, 4% 56%, 4% 44%, 12% 38%, 38% 38%);
}
/* the CLASSIC lettering is white, so on the light theme darken the picture and the + */
html.skin-theme-clientpref-day .aa-tree-mark img { filter: brightness(0.25); }
html.skin-theme-clientpref-day .aa-tree-mark::after { background: #b5651d; }
@media (prefers-color-scheme: light) {
  html.skin-theme-clientpref-os .aa-tree-mark img { filter: brightness(0.25); }
  html.skin-theme-clientpref-os .aa-tree-mark::after { background: #b5651d; }
}
.aa-tree-mark img {
  display: block;
}

