html.skin-theme-clientpref-os .aa-tree,
html.skin-theme-clientpref-os .aa-tree-ptip { background: linear-gradient(to bottom, rgba(46, 38, 32, .98), rgba(27, 21, 17, .98)); border-color: #6a5340; border-radius: 10px; box-shadow: 0 0 0 1px rgba(0, 0, 0, .55), 0 6px 18px rgba(0, 0, 0, .6); color: #e8e1d6; }
html.skin-theme-clientpref-os .aa-tree-ptext { color: #e8e1d6; }
html.skin-theme-clientpref-os .aa-tree-pkind { color: #c9bfb0; }
html.skin-theme-clientpref-os .aa-tree-ico { color: #9a9082; }
html.skin-theme-clientpref-os .aa-tree-pname { color: #ffffff; }
html.skin-theme-clientpref-os .aa-tree-hl { color: #ff9c27; }
html.skin-theme-clientpref-os .aa-tree-sep { border-top-color: #6a5340; }
html.skin-theme-clientpref-os .aa-tree-name,
html.skin-theme-clientpref-os .aa-tree-title { color: #ffffff; text-shadow: none; }
html.skin-theme-clientpref-os .aa-tree-tile { background: #241d18; border-color: #241d18; outline-color: #6a5340; }
html.skin-theme-clientpref-os .aa-tree-tile:hover,
html.skin-theme-clientpref-os .aa-tree-tile:focus { outline-color: var(--aa-accent); }
}

/* a lazy skill card ({{SkillLink|id|tree=...}}, TreeSkills, TreeCombo): the box stays closed until Common.js has put the card in it */
.aa-lazy > .aa-skilltip-card:empty {
  display: none !important;
}
.aa-lazy[data-aa-lazy="loading"] {
  cursor: progress;
}
